/* Two three-float corners of a box (x and y negated when ScrmIsFieldFlipped is
   set). Each object BigObjInstGet lists whose x and y lie inside the box gets
   x and y moved: past the corner on the side farther from it, by
   2 * (1 + 0.05 * SyncRandGetRange(0, 50)), unless already beyond that, and
   the result goes to PhysSetObjectPosition for the matching BigObjGet owner. */
extern "C" void AnmsClearObjectsFromArea(void)
{
    float lo[3];
    float hi[3];
    float pos[3];
    int i;

    lo[0] = ScrmIsFieldFlipped() ? -lbl_802D72A4.mX : lbl_802D72A4.mX;
    lo[1] = ScrmIsFieldFlipped() ? -lbl_802D72A4.mY : lbl_802D72A4.mY;
    lo[2] = lbl_802D72A4.mZ;
    hi[0] = ScrmIsFieldFlipped() ? -lbl_802D72B0.mX : lbl_802D72B0.mX;
    hi[1] = ScrmIsFieldFlipped() ? -lbl_802D72B0.mY : lbl_802D72B0.mY;
    hi[2] = lbl_802D72B0.mZ;
    for (i = 0; i < BigObjGetCount(); i++) {
        BigObjInst *pObject = BigObjInstGet(i);

        pos[0] = pObject->mState.mUnknown0;
        pos[1] = pObject->mState.mUnknown4;
        pos[2] = pObject->mState.mUnknown8;
        if (pos[0] >= lo[0] && pos[0] <= hi[0] && pos[1] >= lo[1] && pos[1] <= hi[1]) {
            float margin = 2.0f * (SyncRandGetRange(0, 50) * 0.05f + 1.0f);

            if (hi[0] - pos[0] > pos[0] - lo[0]) {
                pos[0] = (hi[0] + margin >= pos[0]) ? hi[0] + margin : pos[0];
            } else {
                pos[0] = (lo[0] - margin <= pos[0]) ? lo[0] - margin : pos[0];
            }
            margin = 2.0f * (SyncRandGetRange(0, 50) * 0.05f + 1.0f);
            if (hi[1] - pos[1] > pos[1] - lo[1]) {
                pos[1] = (hi[1] + margin >= pos[1]) ? hi[1] + margin : pos[1];
            } else {
                pos[1] = (lo[1] - margin <= pos[1]) ? lo[1] - margin : pos[1];
            }
            PhysSetObjectPosition(BigObjGet(i), pos);
        }
    }
}

/* Places character index's players at the start of its actor. When the
   first player's id byte +3 is 1 it is set up first: if fn_800AD9B4
   returns 1 or 7 it goes to the origin and its facing alternates between
   0 and 0x800000 on each call; otherwise character kind 1 takes
   GamebreakerSceneAdjustSpot's spot facing 0x400000, kinds 0 and 5 keep it, and other kinds (kind 3 with sub-kind up to 7 faces 0x400000,
   the rest face 0x800000 for positive x) are clamped to x in [-1, 1] and
   y within ScrmGetEndLineY() - 8. AnimSeqPushPlayersFromArea then runs, and every player
   gets its frame spot and facing from AnmsGetCastSpot unless actor flag
   0x400 is set. */


extern "C" int AnmsPlaceCast(int index)
{
    Character_80093BCC *pCharacter = fn_80093BCC(index);
    Actor_801C009C *pActor = AnmsGetScript(pCharacter->mUnknown0, pCharacter->mUnknown4);
    Object_80039F5C *p = pCharacter->mUnknown14[0];
    unsigned short i;

    if (p->mIdBytes[3] == 1) {
        if (fn_800AD9B4() == 1 || fn_800AD9B4() == 7) {
            p->mMotion.mPos.mX = 0.0f;
            p->mMotion.mPos.mY = 0.0f;
            p->mMotion.mFacing = lbl_803EA8CC != 0 ? 0x800000 : 0;
            lbl_803EA8CC = (lbl_803EA8CC + 1) & 1;
        } else {
            int kind = pCharacter->mUnknown4;

            if (kind != 5) {
                if (kind == 1) {
                    GamebreakerSceneAdjustSpot((FieldPoint_t *)&p->mMotion.mPos);
                    p->mMotion.mFacing = 0x400000;
                } else if (kind != 0) {
                    float limit;

                    if (kind == 3 && (unsigned int)pCharacter->mUnknown0 <= 7) {
                        p->mMotion.mFacing = 0x400000;
                    } else if (p->mMotion.mPos.mX > 0.0f) {
                        p->mMotion.mFacing = 0x800000;
                    } else {
                        p->mMotion.mFacing = 0;
                    }
                    limit = 1.0f;
                    if (p->mMotion.mPos.mX < -limit) {
                        p->mMotion.mPos.mX = -limit;
                    } else if (p->mMotion.mPos.mX > limit) {
                        p->mMotion.mPos.mX = limit;
                    }
                    limit = ScrmGetEndLineY() - 8.0f;
                    if (p->mMotion.mPos.mY < -limit) {
                        p->mMotion.mPos.mY = -limit;
                    } else if (p->mMotion.mPos.mY > limit) {
                        p->mMotion.mPos.mY = limit;
                    }
                }
            }
        }
        pCharacter->mUnknown8 |= 0x20;
    }
    AnimSeqPushPlayersFromArea(pCharacter, pActor, p);
    for (i = 0; i < pActor->mUnknown4; i++) {
        Vector_80039F5C spot;
        int angle;
        unsigned char found;
        int result;

        p = pCharacter->mUnknown14[i];
        if ((unsigned int)pCharacter->mUnknown4 <= 2 && p->mUnknown9[2] != 0) {
            p->mpUnknown4->mUnknown20 |= 1;
        }
        if (pActor->mUnknown8 & 0x400) {
            p->mpUnknown4->mUnknown20 |= 0x2000;
            pCharacter->mUnknown8 |= 0x20;
        }
        result = AnmsGetCastSpot(pCharacter, p, pCharacter->mUnknown14[0], i, &spot, &angle);
        AnmsFindCastTag(pCharacter, 0x434C4950 /* 'CLIP' */, 0, &found);
        if (result != 0) {
            pCharacter->mUnknown8 |= 8;
        }
        if (found != 0) {
            pCharacter->mUnknown8 |= 0x20;
        }
        if (!(pActor->mUnknown8 & 0x400)) {
            MotionClear(&p->mMotion);
            p->mUnknown500 = 0;
            p->mUnknown504 = 0.0f;
            p->mMotion.mPos.mX = spot.mX;
            p->mMotion.mPos.mY = spot.mY;
            p->mMotion.mPos.mZ = spot.mZ;
            p->mMotion.mUnknown12.mX = spot.mX;
            p->mMotion.mUnknown12.mY = spot.mY;
            p->mMotion.mUnknown12.mZ = spot.mZ;
            p->mpUnknown796->mUnknown8 = p->mMotion.mFacing = angle;
        }
    }
    AnmsPlaceBallObjects(index);
    return 1;
}

