        case 5:
            pOut->mX = pFrame->mUnknown24 = -15.535f;
            pOut->mY = pFrame->mUnknown1C = 21.259f;
            pOut->mZ = pFrame->mUnknown20 = 0.0f;
            break;
        case 7:
            pOut->mX = pFrame->mUnknown24 = -15.658f;
            pOut->mY = pFrame->mUnknown1C = -2.154f;
