/* Spot and 24-bit facing for p at frame frameIndex of character's actor.
   With actor flag 0x400 the actor's first frame moves pRef by its offset and
   turn (or p copies pRef) and p's own spot is returned. Otherwise the start
   comes from AnmsGetStartSpot, and a nonzero frameIndex takes that frame's
   offset and turn: flag 0x10 keeps p's spot, flag 0x20 turns the offset
   through the matrix stack around the start. For index 0 AnimSeqncrGetPlayerPtr
   returns the actor's +0x18 record; other indexes return 0x30-byte entries
   of the array at actor +0x1C. Only fields below +0x30 (+0x18..+0x24) are
   read from that frame, and those offsets line up in both, so the
   Frame_80141210 view is used for it. */
extern "C" int AnmsGetCastSpot(Character_80093BCC *pCharacter, Object_80039F5C *p, Object_80039F5C *pRef,
                           unsigned short frameIndex, Vector_80039F5C *pOut, int *pAngle)
{
    Vector_80039F5C spot;
    Vector_80039F5C start;
    int angles[3];
    int angle;
    Actor_801C009C *pActor = AnmsGetScript(pCharacter->mUnknown0, pCharacter->mUnknown4);

    if (pActor->mUnknown8 & 0x400) {
        Frame_80141210 *pFrame = AnimSeqncrGetFirstPlayerPtr(pActor);

        if (!(pActor->mUnknown8 & 0x800)) {
            p->mMotion.mFacing = 0;
            p->mMotion.mPos.mX = 0.0f;
            p->mMotion.mPos.mY = 0.0f;
            p->mMotion.mPos.mZ = 0.0f;
            p->mpUnknown796->mUnknown8 = 0;
        }
        pActor->mUnknown18->mUnknown30 = -pFrame->mUnknown18;
        pFrame->mUnknown34 = 0.0f;
        pFrame->mUnknown38 = 0.0f;
        pFrame->mUnknown3C = 0.0f;
        if (p == pRef) {
            pRef->mMotion.mPos.mX += pFrame->mUnknown1C;
            pRef->mMotion.mPos.mY += pFrame->mUnknown20;
            pRef->mMotion.mPos.mZ += pFrame->mUnknown24;
            pRef->mMotion.mFacing += (int)(pFrame->mUnknown18 * 2670176.75f);
        } else {
            p->mMotion.mPos = pRef->mMotion.mPos;
            p->mMotion.mFacing = pRef->mMotion.mFacing;
        }
        spot.mX = p->mMotion.mPos.mX;
        spot.mY = p->mMotion.mPos.mY;
        spot.mZ = p->mMotion.mPos.mZ;
        pOut->mX = spot.mX;
        pOut->mY = spot.mY;
        pOut->mZ = spot.mZ;
        *pAngle = p->mMotion.mFacing;
        return 0;
    }
    AnmsGetStartSpot(pCharacter, pActor, pRef, &start, &angle);
    spot.mX = start.mX;
    spot.mY = start.mY;
    spot.mZ = start.mZ;
    if (frameIndex != 0) {
        Frame_80141210 *pFrame = (Frame_80141210 *)AnimSeqncrGetPlayerPtr(pActor, frameIndex);

        if (pActor->mUnknown8 & 0x10) {
            spot.mX = p->mMotion.mPos.mX;
            spot.mY = p->mMotion.mPos.mY;
            spot.mZ = p->mMotion.mPos.mZ;
        } else {
            pCharacter->mUnknown8 |= 0x20;
            if (pActor->mUnknown8 & 0x20) {
                MatPush();
                MatMakeUnit();
                MatTranslate(&start.mX);
                MatRotZ(AnmsGetPlayerFacing(pRef));
                spot.mX = pFrame->mUnknown24;
                spot.mY = pFrame->mUnknown1C;
                spot.mZ = pFrame->mUnknown20;
                MatTranslate(&spot.mX);
                angle = (int)(pFrame->mUnknown18 * 2670176.75f);
                MatRotZ(angle);
                MatGetPos(&spot.mX);
                MatGetRotByOrder(angles, 0);
                angle = angles[2];
                MatPop();
            } else {
                spot.mX = pFrame->mUnknown24;
                spot.mY = pFrame->mUnknown1C;
                spot.mZ = pFrame->mUnknown20;
                angle = (int)(pFrame->mUnknown18 * 2670176.75f);
            }
        }
    }
    pOut->mX = spot.mX;
    pOut->mY = spot.mY;
    pOut->mZ = spot.mZ;
    *pAngle = angle;
    return 0;
}

extern "C" int AnmsGetPlayerFacing(Object_80039F5C *p)
{
    Object_8003DEC4 *pModel;
    Vector_80039F5C offset;
    float matrix[4][4];
    Vec2_t delta;

    if (p->mUnknown9[0] == 8 || p->mUnknown9[0] == 1) {
        return p->mMotion.mFacing;
    }
    pModel = (Object_8003DEC4 *)p->mpUnknown4;
    MatPush();
    MatMulMatrices((float *)matrix, (float *)pModel->mUnknown908, (float *)pModel->mUnknown44.mUnknown52[13]);
    MatLoad((float *)matrix);
    MatGetPos((float *)&offset);
    MatPop();
    if (ScrmIsFieldFlipped() != 0) {
        offset.mX = -offset.mX;
        offset.mY = -offset.mY;
    }
    Vec2Sub(&delta, &p->mMotion.mPos, &offset);
    return MathArcTan2(delta.mY, delta.mX);
}

