/* Situation kind of p, from its +0x1D state and, for state 0, its flags,
   AnmsGetContextValue(1) and the yards AnmsGetPlayYards gives; 14 when nothing applies. */
extern "C" int fn_800948E4(ScrmPlayResult_t *p)
{
    int kind = 14;

    if (p->mUnknown1D != 0) {
        switch (p->mUnknown1D) {
        case 6:
        case 9:
            kind = 2;
            break;
        case 2:
            kind = 11;
            break;
        case -2:
            kind = 8;
            break;
        case 3:
        case -3:
            kind = 3;
            break;
        }
    } else if (AnmsGetPlayKind(p) == 2) {
        kind = 12;
    } else if (p->mUnknown18 & 0x800) {
        kind = 4;
    } else {
        kind = AnmsGetContextValue(1);
        switch (kind) {
        case 6:
        case 7:
        case 9:
        case 10:
            break;
        case 3:
            if (ScrmGetSnapOffense() == ScrmGetOffenseTeam()) {
                kind = 14;
            }
            break;
        case 5:
            if (!(p->mUnknown18 & 0x10000)) {
                break;
            }
            /* fall through */
        default:
            if (p->mUnknown18 & 0x40) {
                kind = 14;
                if (ScrmGetSnapOffense() == ScrmGetOffenseTeam()) {
                    kind = 1;
                }
            } else {
                float yards = AnmsGetPlayYards(p);

                if (yards > 0.0f) {
                    kind = 0;
                } else if (yards < 0.0f) {
                    kind = 13;
                }
            }
            break;
        }
    }
    return kind;
}

