extern "C" int AnmsCastPickNearest(int key, Params_80092E54 *pRequest, Actor_801C009C *pActor, Object_80039F5C *pObject,
                           float range)
{
    int result = 1;
    unsigned int i;

    for (i = 1; i < pActor->mUnknown4; i++) {
        Frame_800DF7CC *pFrame = AnimSeqncrGetPlayerPtr(pActor, i);

        if (AnmsIsFixedCastTag(pFrame->mUnknown0) == key && pRequest->mUnknown14[i] == 0) {
            Object_80039F5C *pCandidates[24];
            unsigned short count;
            Vec2_t target;
            Vec2_t delta;
            Object_80039F5C *pBest = 0;
            float best = range;
            unsigned short j;
            int found;

            target.mX = pObject->mMotion.mPos.mX + pFrame->mUnknown28;
            target.mY = pObject->mMotion.mPos.mY + pFrame->mUnknown32;
            found = AnimSeqListRoleCandidates(pActor, i, pObject, pCandidates, &count);
            for (j = 0; j < count; j++) {
                Object_80039F5C *p = pCandidates[j];

                if (AnmsIsPlayerTaken(p, pRequest, pActor->mUnknown4) == 0) {
                    float distance;

                    Vec2Sub(&delta, &p->mMotion.mPos, &target);
                    distance = Vec2Magnitude(&delta);
                    if (distance < range) {
                        if (pBest == 0) {
                            pBest = p;
                            best = distance;
                        } else if (found && distance < best) {
                            pBest = p;
                            best = distance;
                        }
                        if (!found) {
                            pRequest->mUnknown8 |= 0x10;
                        }
                    }
                }
            }
            pRequest->mUnknown14[i] = pBest;
            if (pBest == 0) {
                result = 0;
                break;
            }
        }
        if (pRequest->mUnknown14[i] != 0) {
            pFrame->mUnknown42 = pRequest->mUnknown14[i]->mpUnknown796->mUnknown2;
        }
    }
    return result;
}

extern "C" int AnmsIsPlayerTaken(Object_80039F5C *p, Params_80092E54 *pRequest, unsigned int count)
{
    int result = 0;
    unsigned short i;

    if (p->mIdBytes[3] == 1) {
        result = p->mpState->mId == 50;
    }
    if (result == 0) {
        for (i = 0; i < count; i++) {
            if (pRequest->mUnknown14[i] == p) {
                result = 1;
                break;
            }
        }
    }
    return result;
}

