/* Camera spot for playback index: by its flags, the ScrmGetBallSpot spot
   (flag 8), that spot pushed 3 forward (0x100), the spot with its depth
   pulled back 7 or 10 depending on ScrmGetGoalLineY (0x200), or the origin.
   Clears *pFlag. */
extern "C" void AnimPlaybackGetCameraSpot(int index, FieldPoint_t *pOut, int *pFlag)
{
    Playback_80096DA8 *pPlayback = AnimPlaybackGet(index);
    FieldPoint_t spot = ScrmGetBallSpot();

    if (pPlayback->mUnknownC & 8) {
        pOut->mY = spot.mY;
        pOut->mX = spot.mX;
    } else if (pPlayback->mUnknownC & 0x200) {
        pOut->mX = spot.mX;
        pOut->mY = spot.mY;
        if (spot.mY < 3.0f - ScrmGetGoalLineY()) {
            pOut->mY -= 7.0f;
        } else {
            pOut->mY -= 10.0f;
        }
    } else if (pPlayback->mUnknownC & 0x100) {
        pOut->mX = spot.mX;
        pOut->mY = spot.mY;
        pOut->mY += 3.0f;
    } else {
        pOut->mX = pOut->mY = 0.0f;
    }
    *pFlag = 0;
}

