extern "C" int CarrierTryMoveOrDive(Object_80039F5C *p, int mode)
{
    Object_800B26B0 *pMotion = &p->mMotion;
    Object_80039F5C *pNearest;
    Object_80039F5C *pOther;
    float distance;
    float otherDistance;
    float limit;

    pNearest = fn_801245DC(p, ScrmGetDefenseTeam(), 0, ScrmGetTeamPlayerCount(ScrmGetDefenseTeam()), 0x200000, &distance, 0);
    pOther = fn_801245DC(p, ScrmGetOffenseTeam(), 0, ScrmGetTeamPlayerCount(ScrmGetOffenseTeam()), 0x200000, &otherDistance, 0);
    if (pNearest == 0 || (pOther != 0 && otherDistance < distance)) {
        pNearest = pOther;
        distance = otherDistance;
    }
    if (pNearest != 0) {
        FieldPoint_t delta;
        int angle;
        int turn;

        Vec2Sub(&delta, &pNearest->mMotion, pMotion);
        angle = MathArcTan2(delta.mY, delta.mX);
        turn = MathAngleDiff(angle, pMotion->mFacing);
        // FAKEMATCH: unused comparison on the kept second MathAngleDiff call; it makes cse build 0x1FFFFF early as the target does
        int facingCarrier = MathAngleDiff((angle + 0x800000) & 0xFFFFFF, pNearest->mMotion.mFacing) <= 0x1FFFFF;
        if (!(distance > 3.0f) && turn <= 0x1FFFFF && !(pNearest->mFlags & 0x800) && CarrierMoveStart(p, mode) != 0) {
            return 1;
        }
    }
    if (pMotion->mUnknown44 > 0.0f) {
        otherDistance = ScrmGetGoalLineY() - pMotion->mPos.mY;
        limit = 7.0f;
        limit *= MathSin(p->mMotion.mFacing);
        if (otherDistance > 0.0f && otherDistance < limit && PlyrTackleStart(p, 2, mode) != 0) {
            StyleTrackerOnStyleFirstDown();
            return 1;
        }
    }
    return CarrierMoveStart(p, mode);
}

