extern "C" int MathClampOffsetRange(int *p, int offset, int *pValue)
{
    int changed = 0;
    int value = *pValue - offset;

    if (value > p[1]) {
        value = p[1];
        changed = 1;
    } else if (value < p[0]) {
        value = p[0];
        changed = 1;
    }
    *pValue = value + offset;
    return changed;
}

