    unsigned int count;
    LevelWall_t *pRow;
    unsigned char i;

    if (ScrmGetSidelineX() - fabsf(pPoint->mX) < 2.0f) {
        nearCorner = ScrmGetEndLineY() - fabsf(pPoint->mY) < 2.0f;
    }
    start.mX = p->mMotion.mPos.mX;
    start.mY = p->mMotion.mPos.mY;
